package gateway
import("net/http";"net/http/httptest";"strings";"testing")
func TestReviewRejectsHEAD(t *testing.T){
 s:=NewServer(":0",goldenAccounts())
 for _,path:=range []string{"/healthz","/accounts","/accounts/a-1"}{
  rec:=httptest.NewRecorder();s.Handler.ServeHTTP(rec,httptest.NewRequest(http.MethodHead,path,nil))
  if rec.Code!=http.StatusMethodNotAllowed{t.Errorf("HEAD %s = %d, want 405",path,rec.Code)}
 }
}
func TestReviewEmptyListIsArray(t *testing.T){
 for _,accounts:=range [][]Account{nil,{}}{
  s:=NewServer(":0",accounts);rec:=httptest.NewRecorder();s.Handler.ServeHTTP(rec,httptest.NewRequest("GET","/accounts",nil))
  if got:=strings.TrimSpace(rec.Body.String());got!="[]"{t.Errorf("GET /accounts with nil=%t = %s, want []",accounts==nil,got)}
 }
}

