// Package outbound provides a small reusable HTTP client for calling a
// trusted downstream service.
package outbound

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"time"
)

// defaultTimeout bounds every request made by Client, guarding against a
// downstream service that stalls indefinitely.
const defaultTimeout = 10 * time.Second

// maxStatusResponseBytes caps how much of the /status response body is
// read, guarding against a downstream service returning an unexpectedly
// large response.
const maxStatusResponseBytes = 64 * 1024

// Client calls a trusted downstream service over HTTP. A Client is safe for
// concurrent use and should be constructed once and reused across calls.
type Client struct {
	baseURL    *url.URL
	httpClient *http.Client
}

// NewClient builds a Client for the given trusted, already-configured base
// URL.
func NewClient(baseURL string) (*Client, error) {
	u, err := url.Parse(baseURL)
	if err != nil {
		return nil, fmt.Errorf("outbound: parse base URL: %w", err)
	}

	return &Client{
		baseURL:    u,
		httpClient: &http.Client{Timeout: defaultTimeout},
	}, nil
}

// StatusResponse is the decoded body of a GET /status response.
type StatusResponse struct {
	State string `json:"state"`
}

// Status fetches GET /status from the configured base URL and returns the
// decoded response. It returns an error for non-2xx responses.
func (c *Client) Status(ctx context.Context) (*StatusResponse, error) {
	endpoint := c.baseURL.JoinPath("status").String()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return nil, fmt.Errorf("outbound: build status request: %w", err)
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("outbound: fetch status: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return nil, fmt.Errorf("outbound: status request failed: %s", resp.Status)
	}

	data, err := io.ReadAll(io.LimitReader(resp.Body, maxStatusResponseBytes+1))
	if err != nil {
		return nil, fmt.Errorf("outbound: read status response: %w", err)
	}
	if len(data) > maxStatusResponseBytes {
		return nil, fmt.Errorf("outbound: status response exceeds %d bytes", maxStatusResponseBytes)
	}

	var status StatusResponse
	if err := json.Unmarshal(data, &status); err != nil {
		return nil, fmt.Errorf("outbound: decode status response: %w", err)
	}

	return &status, nil
}

