	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte(body)) // The client may close early after reaching its limit.
	}))
	t.Cleanup(srv.Close)
	c, err := outbound.NewClient(srv.URL)
	if err != nil {
		t.Fatalf("NewClient(%q) error = %v, want nil", srv.URL, err)
