// Package outbound provides a small HTTP client for calling a status endpoint.
package outbound

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"time"
)

// maxStatusResponseBytes bounds how much of a GET /status response body is
// read, guarding against a service that returns an unexpectedly large body.
const maxStatusResponseBytes = 64 * 1024

// defaultTimeout bounds each request so a stalled service cannot hang a call
// indefinitely, even if the caller-supplied context has no deadline.
const defaultTimeout = 15 * time.Second

// Status is the decoded response body of GET /status.
type Status struct {
	State string `json:"state"`
}

// Client calls a single trusted HTTP service. A Client is safe for reuse
// across calls and should be constructed once and shared.
type Client struct {
	baseURL    string
	httpClient *http.Client
}

// NewClient returns a Client for the given trusted, already-configured base
// URL (e.g. "https://svc.internal:8443").
func NewClient(baseURL string) *Client {
	return &Client{
		baseURL:    baseURL,
		httpClient: &http.Client{Timeout: defaultTimeout},
	}
}

// GetStatus fetches GET /status and returns the decoded response. It returns
// an error if the request fails, the response status is not 2xx, or the
// response body exceeds 64 KiB.
func (c *Client) GetStatus(ctx context.Context) (*Status, error) {
	endpoint, err := url.JoinPath(c.baseURL, "status")
	if err != nil {
		return nil, fmt.Errorf("outbound: build status URL: %w", err)
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return nil, fmt.Errorf("outbound: build status request: %w", err)
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("outbound: fetch status: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode < http.StatusOK || resp.StatusCode >= http.StatusMultipleChoices {
		return nil, fmt.Errorf("outbound: status request returned %d", resp.StatusCode)
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, maxStatusResponseBytes+1))
	if err != nil {
		return nil, fmt.Errorf("outbound: read status response: %w", err)
	}
	if len(body) > maxStatusResponseBytes {
		return nil, fmt.Errorf("outbound: status response exceeds %d bytes", maxStatusResponseBytes)
	}

	var status Status
	if err := json.Unmarshal(body, &status); err != nil {
		return nil, fmt.Errorf("outbound: decode status response: %w", err)
	}
	return &status, nil
}

