// Package outbound provides a small reusable HTTP client for calling a
// trusted upstream service's status endpoint.
package outbound

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"time"
)

// maxStatusResponseBytes bounds how much of a GET /status response body is
// read, protecting against a stalled or unexpectedly large response.
const maxStatusResponseBytes = 64 * 1024

// requestTimeout bounds the overall time allowed for a single request,
// including connection, TLS handshake, and body read.
const requestTimeout = 10 * time.Second

// Client calls a trusted upstream service. It is safe for concurrent use and
// should be constructed once and reused across calls.
type Client struct {
	baseURL    *url.URL
	httpClient *http.Client
}

// NewClient returns a Client that sends requests to baseURL, which must be a
// trusted, already-validated URL.
func NewClient(baseURL string) (*Client, error) {
	u, err := url.Parse(baseURL)
	if err != nil {
		return nil, fmt.Errorf("parse base URL: %w", err)
	}
	return &Client{
		baseURL: u,
		httpClient: &http.Client{
			Timeout: requestTimeout,
		},
	}, nil
}

// Status is the decoded response body of GET /status.
type Status struct {
	State string `json:"state"`
}

// GetStatus fetches GET /status and returns the decoded response. It returns
// an error if the response status is not 2xx.
func (c *Client) GetStatus(ctx context.Context) (Status, error) {
	u := c.baseURL.JoinPath("status")

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
	if err != nil {
		return Status{}, fmt.Errorf("build request: %w", err)
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return Status{}, fmt.Errorf("do request: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode < http.StatusOK || resp.StatusCode >= http.StatusMultipleChoices {
		return Status{}, fmt.Errorf("unexpected status %d from %s", resp.StatusCode, u)
	}

	var status Status
	if err := json.NewDecoder(io.LimitReader(resp.Body, maxStatusResponseBytes)).Decode(&status); err != nil {
		return Status{}, fmt.Errorf("decode response: %w", err)
	}

	return status, nil
}

