	"net/http"
	"slices"
	"time"
)

// Account is one record the API serves.
type Account struct {
	ID     string `json:"id"`
	Name   string `json:"name"`
	Cents  int64  `json:"cents"`
	Active bool   `json:"active"`
}

// gatewayServer holds the account data behind the handlers. The data is
// fixed at construction time and never mutated afterward, so handlers can
// read it concurrently without synchronization.
type gatewayServer struct {
	accounts []Account
	byID     map[string]Account
}

func (s *gatewayServer) handleHealthz(w http.ResponseWriter, r *http.Request) {
	_, _ = w.Write([]byte("ok"))
}

func (s *gatewayServer) handleListAccounts(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query()
	if !query.Has("active") {
		writeJSON(w, http.StatusOK, s.accounts)
		return
	}

	var active bool
	switch query.Get("active") {
	case "true":
		active = true
	case "false":
		active = false
	default:
		http.Error(w, `invalid value for query parameter "active"`, http.StatusBadRequest)
		return
	}

	filtered := make([]Account, 0, len(s.accounts))
	for _, a := range s.accounts {
		if a.Active == active {
			filtered = append(filtered, a)
		}
	}
	writeJSON(w, http.StatusOK, filtered)
}

func (s *gatewayServer) handleGetAccount(w http.ResponseWriter, r *http.Request) {
	a, ok := s.byID[r.PathValue("id")]
	if !ok {
		http.Error(w, "account not found", http.StatusNotFound)
		return
	}
	writeJSON(w, http.StatusOK, a)
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

// NewServer returns the server for the public accounts API, listening on addr
// and serving the given accounts. Starting and stopping it is the caller's job.
//
// This server is the edge: it is published straight to the open internet with
// no proxy of any kind in front of it. Every client is anonymous, some are on
// mobile links that stall mid-request, many hold connections open long after
// they stop asking for anything, and a share of the traffic is there to find
// out what the process can be made to hold onto.
//
// It answers these requests and nothing else:
//
//	GET /healthz         200, body "ok"
//	GET /accounts        200, a JSON array of every account, ordered by ID
//	GET /accounts/{id}   200, the JSON object for that account; 404 if unknown
//
// GET /accounts also takes one optional query parameter, active, which is
// either "true" or "false" and restricts the array to accounts in that state.
// Any other value for it is a 400 whose body names the parameter.
//
// Any other path is a 404. A known path asked for with any method other than
// GET is a 405.
func NewServer(addr string, accounts []Account) *http.Server {
	sorted := make([]Account, len(accounts))
	copy(sorted, accounts)
	slices.SortFunc(sorted, func(a, b Account) int {
		return cmp.Compare(a.ID, b.ID)
	})

	byID := make(map[string]Account, len(sorted))
	for _, a := range sorted {
		byID[a.ID] = a
	}

	s := &gatewayServer{accounts: sorted, byID: byID}

	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", s.handleHealthz)
	mux.HandleFunc("GET /accounts", s.handleListAccounts)
	mux.HandleFunc("GET /accounts/{id}", s.handleGetAccount)

	return &http.Server{
		Addr:              addr,
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
		MaxHeaderBytes:    1 << 20,
	}
}

