package gateway

import (
	"io"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestServerRoutes(t *testing.T) {
	accounts := []Account{
		{ID: "b", Name: "Bob", Cents: 200, Active: false},
		{ID: "a", Name: "Alice", Cents: 100, Active: true},
	}
	srv := NewServer(":0", accounts)
	ts := httptest.NewServer(srv.Handler)
	defer ts.Close()
	c := ts.Client()

	cases := []struct {
		path       string
		method     string
		wantStatus int
		wantBody   string
	}{
		{"/healthz", "GET", 200, "ok"},
		{"/accounts", "GET", 200, `[{"id":"a","name":"Alice","cents":100,"active":true},{"id":"b","name":"Bob","cents":200,"active":false}]` + "\n"},
		{"/accounts?active=true", "GET", 200, `[{"id":"a","name":"Alice","cents":100,"active":true}]` + "\n"},
		{"/accounts?active=false", "GET", 200, `[{"id":"b","name":"Bob","cents":200,"active":false}]` + "\n"},
		{"/accounts?active=bogus", "GET", 400, ""},
		{"/accounts/a", "GET", 200, `{"id":"a","name":"Alice","cents":100,"active":true}` + "\n"},
		{"/accounts/zzz", "GET", 404, ""},
		{"/nope", "GET", 404, ""},
		{"/healthz", "POST", 405, ""},
		{"/accounts", "DELETE", 405, ""},
	}

	for _, tc := range cases {
		req, _ := http.NewRequest(tc.method, ts.URL+tc.path, nil)
		resp, err := c.Do(req)
		if err != nil {
			t.Fatalf("%s %s: %v", tc.method, tc.path, err)
		}
		body, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		if resp.StatusCode != tc.wantStatus {
			t.Errorf("%s %s: status = %d, want %d (body %q)", tc.method, tc.path, resp.StatusCode, tc.wantStatus, body)
		}
		if tc.wantBody != "" && string(body) != tc.wantBody {
			t.Errorf("%s %s: body = %q, want %q", tc.method, tc.path, body, tc.wantBody)
		}
	}
}

