// Package outbound provides a small reusable HTTP client for calling a
// trusted upstream service.
package outbound

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"
)

// maxStatusResponseBytes bounds how much of a /status response body is read,
// guarding against an unexpectedly large or streaming response.
const maxStatusResponseBytes = 64 * 1024

// requestTimeout bounds a single call against a stalled upstream, even if
// the caller's context has no deadline of its own.
const requestTimeout = 10 * time.Second

// Client calls a trusted HTTP service. A Client is safe for concurrent use
// and should be constructed once and reused across calls.
type Client struct {
	baseURL    string
	httpClient *http.Client
}

// NewClient returns a Client that sends requests to baseURL. baseURL must be
// a trusted, already-validated URL; it is not sanitized.
func NewClient(baseURL string) *Client {
	return &Client{
		baseURL:    strings.TrimSuffix(baseURL, "/"),
		httpClient: &http.Client{Timeout: requestTimeout},
	}
}

// StatusResponse is the decoded body of a GET /status response.
type StatusResponse struct {
	State string `json:"state"`
}

// Status fetches GET /status and returns the decoded response. It returns an
// error if the request fails, ctx is done, or the response status is not 2xx.
func (c *Client) Status(ctx context.Context) (*StatusResponse, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.baseURL+"/status", nil)
	if err != nil {
		return nil, fmt.Errorf("outbound: build status request: %w", err)
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("outbound: fetch status: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode < http.StatusOK || resp.StatusCode >= http.StatusMultipleChoices {
		return nil, fmt.Errorf("outbound: status request returned %s", resp.Status)
	}

	var status StatusResponse
	body := io.LimitReader(resp.Body, maxStatusResponseBytes)
	if err := json.NewDecoder(body).Decode(&status); err != nil {
		return nil, fmt.Errorf("outbound: decode status response: %w", err)
	}

	return &status, nil
}

