package outbound_test

import (
	"abeval/outbound"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestReviewRejectsOversizedStatus(t *testing.T) {
	body := `{"state":"ready"}` + strings.Repeat(" ", 64<<10)
	// This client creates its own transport, so use a real loopback server.
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte(body)) // The client may close early after reaching its limit.
	}))
	t.Cleanup(srv.Close)
	c := outbound.NewClient(srv.URL)
	got, err := c.Status(t.Context())
	if err == nil {
		t.Errorf("Status(response bytes=%d) = %+v, nil; want response-size error", len(body), got)
	}
}

