// Package outbound provides a client for calling a status endpoint.
package outbound

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"time"
)

const (
	requestTimeout  = 10 * time.Second
	maxResponseSize = 64 * 1024
)

// Status is the decoded response from GET /status.
type Status struct {
	State string `json:"state"`
}

// Client calls the status endpoint of a configured service. Construct one
// with NewClient and reuse it across calls; it owns its own connection pool.
type Client struct {
	baseURL    string
	httpClient *http.Client
}

// NewClient returns a Client that issues requests against baseURL. baseURL
// must already be a trusted, validated URL.
func NewClient(baseURL string) *Client {
	return &Client{
		baseURL:    baseURL,
		httpClient: &http.Client{Timeout: requestTimeout},
	}
}

// GetStatus fetches GET /status and returns the decoded response. It returns
// an error if the request fails or the response status is not 2xx.
func (c *Client) GetStatus(ctx context.Context) (*Status, error) {
	endpoint, err := url.JoinPath(c.baseURL, "status")
	if err != nil {
		return nil, fmt.Errorf("build status URL: %w", err)
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, endpoint, nil)
	if err != nil {
		return nil, fmt.Errorf("build status request: %w", err)
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("fetch status: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return nil, fmt.Errorf("fetch status: unexpected status %d", resp.StatusCode)
	}

	var status Status
	if err := json.NewDecoder(io.LimitReader(resp.Body, maxResponseSize)).Decode(&status); err != nil {
		return nil, fmt.Errorf("decode status: %w", err)
	}
	return &status, nil
}

